// «История буфера»: what must never be kept. Decided before anything is stored, never after.
// - Copies marked by the app that made them: macOS pasteboard types of password managers (nspasteboard.org
//   «Concealed» / «Transient» / «AutoGenerated», 1Password's own), Windows formats that ask clipboard managers to skip
//   the content («ExcludeClipboardContentFromMonitorProcessing», «CanIncludeInClipboardHistory», «Clipboard Viewer
//   Ignore»).
// - Copies made while a password manager (the activity tracker's list, src/activity/redact.cjs) or an app from the
//   user's own list was in front.
// - Text that looks like a password or a token: private keys, «password: …» / «token=…» lines, credentials in a URL,
//   tokens with a known service prefix, JWTs, and single words that look random (letters and digits mixed with
//   symbols, or long high-entropy strings). Over-skipping is the safe side.
const {PRIVATE_APPS,entries}=require('../../activity/redact.cjs');

const MARKERS=['org.nspasteboard.ConcealedType','org.nspasteboard.TransientType','org.nspasteboard.AutoGeneratedType','com.agilebits.onepassword',
 'ExcludeClipboardContentFromMonitorProcessing','CanIncludeInClipboardHistory','Clipboard Viewer Ignore'];
function marked(formats){const list=(formats||[]).map(String);return MARKERS.find(m=>list.some(f=>f===m||f.toLowerCase()===m.toLowerCase()))||'';}

const lower=v=>String(v||'').toLocaleLowerCase().replace(/ё/g,'е');
// The app in front is a password manager or on the user's list.
function privateApp(app,list=''){
 const k=lower(app).trim();if(!k)return false;
 if(PRIVATE_APPS.some(p=>lower(p)===k||k.startsWith(lower(p)+' ')))return true;
 return entries(list).some(e=>{const x=lower(e);return k===x||k.includes(x);});
}

const PEM=/-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----|-----BEGIN OPENSSH PRIVATE KEY-----|-----BEGIN PGP PRIVATE KEY BLOCK-----/;
const ASSIGN=/(?:^|[\s"'{,;?&])(?:pass(?:word|wd|phrase)?|pwd|secret|token|api[_ -]?key|apikey|access[_ -]?key|secret[_ -]?key|private[_ -]?key|client[_ -]?secret|auth|bearer|пароль|токен|секрет)\s*["']?\s*(?:[:=]|=>|\s)\s*["']?([^\s"']{6,})/giu;
// A labelled value that only refers to a secret kept elsewhere: an environment variable, a template, a config field.
const REFERENCE=/^(?:process\.env|os\.environ|getenv|env\(|\$\{|\$[A-Z_]|<|\{\{|%|config\.|settings\.|this\.|self\.|secrets\.|[A-Z][A-Z0-9_]*$)/;
const assigned=t=>[...t.matchAll(ASSIGN)].some(m=>!REFERENCE.test(m[1]));
const BEARER=/\b(?:Bearer|Basic)\s+[A-Za-z0-9._~+/=-]{16,}/;
const URL_CREDENTIALS=/[a-z][a-z0-9+.-]*:\/\/[^\s/:@]+:[^\s/@]{3,}@/i;
// Service tokens by their documented prefixes (GitHub, GitLab, Slack, AWS, Google, OpenAI/Stripe-style, npm, JWT).
const PREFIXED=[/^gh[pousr]_[A-Za-z0-9]{30,}$/,/^github_pat_[A-Za-z0-9_]{40,}$/,/^glpat-[A-Za-z0-9_-]{16,}$/,/^xox[abposr]-[A-Za-z0-9-]{10,}$/,/^xapp-[A-Za-z0-9-]{10,}$/,
 /^A(?:KIA|SIA)[0-9A-Z]{16}$/,/^AIza[0-9A-Za-z_-]{30,}$/,/^ya29\.[0-9A-Za-z_-]{20,}$/,/^(?:sk|rk|pk)[-_](?:live|test|proj|ant|or)?[-_]?[A-Za-z0-9_-]{16,}$/,/^npm_[A-Za-z0-9]{30,}$/,
 /^eyJ[A-Za-z0-9_-]{8,}\.eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}$/,/^dop_v1_[a-f0-9]{40,}$/,/^shpat_[a-fA-F0-9]{20,}$/];

function entropy(s){const n={};for(const c of s)n[c]=(n[c]||0)+1;let e=0;for(const k in n){const p=n[k]/s.length;e-=p*Math.log2(p);}return e;}
// Letter↔digit switches: «Xk9mP2qL7» switches often, «int32Array» or «utf8» do not.
const switches=s=>{let n=0;for(let i=1;i<s.length;i++)if(/\d/.test(s[i])!==/\d/.test(s[i-1]))n++;return n;};
// Things people copy that only look random: links, e-mail, paths, numbers, dates, versions, UUIDs, hashes, identifiers.
const PLAIN=[/^[a-z][a-z0-9+.-]*:\/\//i,/^www\./i,/^[\w.+-]+@[\w-]+(?:\.[\w-]+)+$/,/^(?:[A-Za-z]:)?[\\/~.]/,/^[+-]?\d[\d\s.,:/-]*$/,/^v?\d+(?:\.\d+){1,3}(?:[-+][\w.]+)?$/,
 /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i,/^[0-9a-f]{7,64}$/i,/^[A-Z][A-Z0-9_]{0,19}-\d{1,9}$/,/^#[0-9a-f]{3,8}$/i];

function word(w){
 if(PREFIXED.some(r=>r.test(w)))return 'token';
 if(w.length<8||w.length>256||PLAIN.some(r=>r.test(w)))return '';
 const letters=/\p{L}/u.test(w),digits=/\d/.test(w),symbols=/[!@#$%^&*()+=?~`|<>{}[\];,'"\\]/.test(w),cases=/[A-Z]/.test(w)&&/[a-z]/.test(w);
 // «electron@39» stays; «Tr0ub4dor&3» does not.
 if(letters&&digits&&symbols&&(cases||switches(w)>=2)&&w.length<=64)return 'password';
 // «int32Array», «utf8Decoder», «user_id_123» stay; «Xk9mP2qL7» does not.
 if(letters&&digits&&cases&&switches(w)>=3&&w.length<=64)return 'password';
 if(w.length>=20&&/^[A-Za-z0-9+/=_.-]+$/.test(w)&&letters&&digits&&(cases||switches(w)>=4)&&entropy(w)>=3.5)return 'token';
 return '';
}
// '' when the text may be kept; otherwise why not ('key', 'password', 'credentials', 'token').
function looksSecret(text){
 const t=String(text||'').trim();if(!t)return '';
 if(PEM.test(t))return 'key';
 if(URL_CREDENTIALS.test(t))return 'credentials';
 if(BEARER.test(t))return 'token';
 if(assigned(t))return 'password';
 // A short text is checked word by word; a long one only for tokens that stand out.
 const words=t.split(/\s+/).map(w=>w.replace(/^[«"'(<[]+|[»"')>\].,;:!?]+$/g,'')).filter(Boolean);
 for(const w of words.length<=6?words:words.filter(w=>w.length>=20)){const r=word(w);if(r)return r;}
 return '';
}
module.exports={looksSecret,marked,privateApp,entropy,MARKERS};
